-- Seed PRODIGIO — 71 prospects réels issus de PRODIGIO-prospection-master.xlsx.
-- À exécuter UNE FOIS dans Supabase → SQL Editor, après schema.sql.
-- Idempotent par (app, prodigio_type, entreprise) : relancer ne crée pas de doublons.

create unique index if not exists prospects_prodigio_uniq
  on prospects (app, prodigio_type, entreprise)
  where app = 'prodigio';

on conflict (app, prodigio_type, entreprise) where app = 'prodigio'
do nothing;
